def get_user_answer():
    """Get user input for a trivia question."""
    while True:
        user_answer = input("Enter 'yes' or 'no': ").lower()
        if user_answer in ['yes', 'no']:
            return user_answer
        else:
            print("Invalid input. Please enter 'yes' or 'no'.")

def play_trivia():
    """Play a trivia game with three questions and keep track of the score."""
    questions = [
        "Who is the current Prime Minister of the UK?",
        "What is the name of the largest moon of Jupiter?",
        "Which country has the most UNESCO World Heritage Sites?"
    ]

    answers = [
        "<NAME>",
        "Ganymede",
        "China"
    ]

    score = 0

    for question, answer in zip(questions, answers):
        user_answer = get_user_answer()
        if user_answer == answer:
            print(f"Correct! The answer is {answer}.")
            score += 1
        else:
            print(f"Incorrect. The correct answer is {answer}.")

    print(f"You scored {score} out of 3.")

if __name__ == "__main__":
    play_trivia()
```

This program defines three trivia questions and their corresponding answers. It then defines a function `get_user_answer()` that prompts the user for a yes/no answer and validates the input. Finally, the `play_trivia()` function plays the game by asking the user three trivia questions, keeping track of the score, and displaying the final score.
